-- ============================================================================
-- شركاؤنا — Seed all 6 partner pages with real content from /Our partners/*.html
--
-- NON-DESTRUCTIVE: UPDATE existing rows + INSERT missing rows.
-- No DELETE, TRUNCATE, or DROP. Safe to run multiple times.
-- ============================================================================

DO $$
