    INSERT INTO pages (title, slug, status) VALUES ('LeFouilleurma', '/partners/lefouilleurma', 'published') RETURNING id INTO v_pid;
  END IF;
  -- Section 1 — Hero
  UPDATE page_sections SET section_type = 'hero', content = '{"heading":"LeFouilleurma","subheading":"شريك وطني","description":"شريك وطني للجمعية المغربية لهواة البحث والاستكشاف، متخصص في بيع وشراء أجهزة الكشف عن المعادن والكنوز على المستوى الوطني.","backgroundImage":"","buttons":[{"id":"btn-pr-website","label":"زيارة الموقع الإلكتروني","url":"#","variant":"primary"},{"id":"btn-pr-contact","label":"تواصل مع الشريك","url":"#prForm","variant":"secondary"}]}'::jsonb, settings='{}'::jsonb, styles='{}'::jsonb WHERE page_id = v_pid AND sort_order = 1;
