  UPDATE page_sections SET section_type = 'custom', content = '{"_renderer":"partnerAbout","eyebrow":"عن LeFouilleurma","heading":"LeFouilleurma","paragraphs":["LeFouilleurma هي شركة مغربية متخصصة في بيع وشراء أجهزة الكشف عن المعادن والكنوز. تقدم الشركة مجموعة واسعة من الأجهزة المتطورة لتلبية احتياجات الهواة والمحترفين على حد سواء.","نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة وطنية تهدف إلى توفير أحدث أجهزة الكشف والتنقيب لأعضاء الجمعية بأسعار تفضيلية."]}'::jsonb, settings='{}'::jsonb, styles='{}'::jsonb WHERE page_id = v_pid AND sort_order = 2;
